import { Navigate } from "react-router-dom";

import { useAuth } from "../contexts/AuthContext";

const ProtectedRoute = ({ children, role }) => {

    const {
        user,
        loading,
        isAuthenticated
    } = useAuth();

    if (loading) {

        return (
            <div>
                Loading...
            </div>
        );

    }

    if (!isAuthenticated) {


        return (

            <Navigate
                to="/login"
                replace
            />

        );

    }

    if (role && user?.role !== role) {


        return (

            <Navigate
                to="/"
                replace
            />

        );

    }

    return children;
};

export default ProtectedRoute;
